def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    from collections import deque
    q = deque()
    for r in range(h):
        for c in range(w):
            if (r == 0 or c == 0 or r == h - 1 or c == w - 1) and grid[r][c] == 8:
                seen.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 8 and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 and (r,c) not in seen:
                out[r][c] = 7
    return out

